package io.rift.cronos;
import android.content.*;import android.database.*;import android.database.sqlite.*;import androidx.test.ext.junit.runners.AndroidJUnit4;import androidx.test.platform.app.InstrumentationRegistry;import org.junit.*;import org.junit.runner.RunWith;import org.json.*;import java.io.File;import java.util.*;import java.util.concurrent.*;import static org.junit.Assert.*;
/** Three isolated actual-SQLite tests; compile does not imply execution. No network or credentials. */
@RunWith(AndroidJUnit4.class)
public final class DiscoveryIndexStoreInstrumentedTest {
 private Context target,isolated;private String prefix;private DiscoveryIndexStore store;
 private static final String A="0x"+"a".repeat(40),B="0x"+"b".repeat(40),C="0x"+"c".repeat(40);
 @Before public void before(){target=InstrumentationRegistry.getInstrumentation().getTargetContext();prefix="test-"+UUID.randomUUID()+"-";isolated=new ContextWrapper(target){@Override public File getDatabasePath(String n){return target.getDatabasePath(prefix+n);}@Override public SQLiteDatabase openOrCreateDatabase(String n,int m,SQLiteDatabase.CursorFactory f){return target.openOrCreateDatabase(prefix+n,m,f);}@Override public SQLiteDatabase openOrCreateDatabase(String n,int m,SQLiteDatabase.CursorFactory f,DatabaseErrorHandler h){return target.openOrCreateDatabase(prefix+n,m,f,h);}};store=new DiscoveryIndexStore(isolated);}
 @After public void after(){if(store!=null)store.close();target.deleteDatabase(prefix+"rift-discovery-indices.sqlite");}
 @Test public void reopenProfileClearAndEpochPreventResurrection()throws Exception{String a=DiscoveryIndex.scope(A,C,"ERC-721"),b=DiscoveryIndex.scope(B,C,"ERC-721");assertTrue(store.commit(a,0,new JSONObject().put("marker",1)));assertTrue(store.commit(b,1,new JSONObject().put("marker",2)));store.close();store=new DiscoveryIndexStore(isolated);assertEquals(1,store.load(a).state.getInt("marker"));long stale=store.load(a).revision;store.clearAccount("25:"+A);assertNull(store.load(a).state);assertEquals(2,store.load(b).state.getInt("marker"));assertFalse(store.commit(a,stale,new JSONObject().put("marker",3)));assertNull(store.load(a).state);}
 @Test public void scopeAndByteCapsRollbackWithoutAdvancingEpoch()throws Exception{String first=DiscoveryIndex.scope(A,C,"ERC-721");try{store.commit(first,0,new JSONObject().put("large","x".repeat(131073)));fail("byte overflow accepted");}catch(IllegalArgumentException expected){}assertEquals(0,store.load(first).revision);for(int i=0;i<16;i++){String c="0x"+String.format(Locale.ROOT,"%040x",i);assertTrue(store.commit(DiscoveryIndex.scope(A,c,"ERC-721"),i,new JSONObject().put("i",i)));}String extra=DiscoveryIndex.scope(B,C,"ERC-721");try{store.commit(extra,16,new JSONObject());fail("scope overflow");}catch(IllegalStateException expected){}assertEquals(16,store.load(extra).revision);String old=DiscoveryIndex.scope(A,"0x"+"0".repeat(40),"ERC-721");assertTrue(store.commit(old,16,null));assertTrue(store.commit(extra,17,new JSONObject().put("ok",true)));}
 @Test public void concurrentHelpersAllowOnlyOneGlobalRevisionCommit()throws Exception{DiscoveryIndexStore second=new DiscoveryIndexStore(isolated);ExecutorService pool=Executors.newFixedThreadPool(2);String scope=DiscoveryIndex.scope(A,C,"ERC-721");try{assertEquals(0,store.load(scope).revision);assertEquals(0,second.load(scope).revision);List<Future<Boolean>> result=pool.invokeAll(Arrays.asList(()->store.commit(scope,0,new JSONObject().put("value",1)),()->second.commit(scope,0,new JSONObject().put("value",2))));assertNotEquals(result.get(0).get(),result.get(1).get());assertEquals(1,store.load(scope).revision);assertNotNull(store.load(scope).state);}finally{pool.shutdownNow();second.close();}}
}
